model:
sample_tank_inspections:TankInspection a owl:Class ;
    rdfs:label "tank inspection"@en ;
    skos:definition "A made-up check of the condition of one storage tank on one date, whose record a system holds."@en ;
    owl:disjointWith sys:System .

sample_tank_inspections:inspectionDate a owl:DatatypeProperty ;
    rdfs:label "inspection date"@en ;
    skos:definition "The date on which the inspection took place."@en ;
    rdfs:domain sample_tank_inspections:TankInspection ;
    rdfs:range xsd:date .

sample_tank_inspections:recordedIn a owl:ObjectProperty ;
    rdfs:label "recorded in"@en ;
    skos:definition "The system that holds the record of the inspection."@en ;
    rdfs:domain sample_tank_inspections:TankInspection ;
    rdfs:range sys:System .

shapes:
shp:TankInspection a sh:NodeShape ;
    sh:targetClass sample_tank_inspections:TankInspection ;
    sh:property [ sh:path sample_tank_inspections:inspectionDate ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:date ;
                  sh:message "An inspection has exactly one date." ] ;
    sh:property [ sh:path sample_tank_inspections:recordedIn ; sh:minCount 1 ; sh:maxCount 1 ; sh:class sys:System ;
                  sh:message "An inspection is recorded in exactly one system of the system module." ] .

examples.pass:
ex:inspection-1 a sample_tank_inspections:TankInspection ;
    sample_tank_inspections:inspectionDate "2026-11-02"^^xsd:date ;
    sample_tank_inspections:recordedIn system:aps-planning-db .
